	scwin.onpageunload = function() {

	};


    scwin.button1_onclick = function() {
        gridView1.setColumnIncrement("Quantity", 0.1);
    }
    scwin.button2_onclick = function() {
        var val = gridView1.getColumnIncrement("Quantity");
        console.log(val);
		window.checkLog = val;
    }

	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}		
	scwin.checkVal1 = function() {
		return window.checkLog == '0.1';
	}		
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___spinner_Quantity___input').value == '300.1';
	}			
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('button1').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('button2').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_1_2')");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___spinner_Quantity_upButton').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");				

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
